+import { readdirSync, readFileSync } from "node:fs";
+import { join, resolve } from "node:path";
+
+import { describe, expect, it } from "vitest";
+
+/**
+ * profile-todo-cleanup — AC-1 and AC-2: the stale workspace TODO is gone from
+ * features/profile/, and the doc comment above getProfileData states that the
+ * profile is per person, so the function takes no organization id.
+ *
+ * The needles are built from parts so that this file, which lives under the
+ * tree it searches, never holds them literally (it is skipped anyway).
+ */
+
+const PROFILE_DIR = join(process.cwd(), "features", "profile");
+const THIS_FILE = resolve(__filename);
+
+const STALE_PHRASE = ["multi-workspace", "support"].join(" ");
+const TODO_MARKER = ["TO", "DO"].join("");
+const ORG_ID_PARAM = ["organization", "Id"].join("");
+
+/** Every file under `dir`, walked recursively. */
+function listFiles(dir: string): string[] {
+  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
+    const path = join(dir, entry.name);
+    if (entry.isDirectory()) return listFiles(path);
+    return entry.isFile() ? [path] : [];
+  });
+}
+
+/** The comment's text with the `*` prefixes and line breaks folded away. */
+const commentText = (block: string) =>
+  block
+    .split("\n")
+    .map((line) => line.replace(/^\s*\/?\*+\/?/, "").replace(/\*\/\s*$/, ""))
+    .join(" ")
+    .replace(/\s+/g, " ");
+
+describe("profile-todo-cleanup", () => {
+  it("AC-1: no file under features/profile/ mentions the stale workspace phrase or holds a TODO line about an organization id parameter", () => {
+    const files = listFiles(PROFILE_DIR).filter(
+      (path) => resolve(path) !== THIS_FILE,
+    );
+    expect(files.length).toBeGreaterThan(0);
+
+    const phraseMatches: string[] = [];
+    const todoMatches: string[] = [];
+    for (const path of files) {
+      const text = readFileSync(path, "utf8");
+      if (text.includes(STALE_PHRASE)) phraseMatches.push(path);
+      text.split("\n").forEach((line, index) => {
+        if (line.includes(TODO_MARKER) && line.includes(ORG_ID_PARAM)) {
+          todoMatches.push(`${path}:${index + 1}`);
+        }
+      });
+    }
+
+    expect(phraseMatches).toEqual([]);
+    expect(todoMatches).toEqual([]);
+  });
+
+  it("AC-2: the doc comment directly above getProfileData says the profile is per person, not per workspace, and that it takes no organization id", () => {
+    const source = readFileSync(
+      join(PROFILE_DIR, "services", "get-profile.ts"),
+      "utf8",
+    );
+
+    const declaration = source.indexOf("export async function getProfileData(");
+    expect(declaration).toBeGreaterThan(-1);
+
+    const before = source.slice(0, declaration).trimEnd();
+    expect(before.endsWith("*/")).toBe(true);
+    const start = before.lastIndexOf("/**");
+    expect(start).toBeGreaterThan(-1);
+
+    const comment = commentText(before.slice(start));
+    expect(comment).toMatch(/per person/i);
+    expect(comment).toMatch(/not per workspace/i);
+    expect(comment).toMatch(/no organization id/i);
+  });
+});
